function policy(obs, params, mem) {
  var PI = Math.PI;

  function clamp(x, lo, hi) {
    return x < lo ? lo : (x > hi ? hi : x);
  }

  function read(i, fallback) {
    var x = obs && obs[i];
    return typeof x === "number" && isFinite(x) ? x : fallback;
  }

  function par(i, lo, hi, fallback) {
    var z = (fallback - lo) * 2 / (hi - lo) - 1;
    if (params && typeof params.length === "number" &&
        i < params.length && typeof params[i] === "number" &&
        isFinite(params[i])) {
      z = params[i];
    }
    z = clamp(z, -1, 1);
    return lo + (z + 1) * 0.5 * (hi - lo);
  }

  function wrap(x) {
    x = (x + PI) % (2 * PI);
    if (x < 0) x += 2 * PI;
    return x - PI;
  }

  var freq = par(0, 0.9, 2.7, 1.75);
  var phase0 = par(1, -PI, PI, 0);
  var hipBias = par(2, -0.4, 0.4, 0.03);
  var hipAmp = par(3, 0.15, 0.95, 0.58);
  var hipShape = par(4, -0.25, 0.25, 0);
  var kneeBase = par(5, -0.30, -0.055, -0.12);
  var kneeFlex = par(6, 0.15, 1.3, 0.78);
  var kneePhase = par(7, -0.8, 0.8, 0);
  var balanceGain = par(8, -1.5, 1.5, 0.75);
  var balanceSpin = par(9, -0.5, 0.5, 0.15);
  var hipKp = par(10, 0.12, 1.0, 0.50);
  var hipKd = par(11, 0.015, 0.18, 0.075);
  var kneeKp = par(12, 0.12, 1.0, 0.45);
  var kneeKd = par(13, 0.015, 0.18, 0.075);
  var desiredHeight = par(14, 0.9, 1.28, 1.07);
  var heightGain = par(15, 0, 1.5, 0.75);
  var syncGain = par(16, 0, 0.4, 0.10);
  var speedGain = par(17, -0.25, 0.25, 0.05);
  var targetSpeed = par(18, 0.5, 3.5, 2.0);

  var torsoAngle = read(0, 0);
  var torsoSpin = read(1, 0);
  var vx = read(2, 0);
  var height = read(4, 1.07);
  var footA = read(9, 0) > 0.5;
  var footB = read(14, 0) > 0.5;
  var t = read(19, 0);

  var terrain = Math.max(
    0,
    read(15, 0),
    0.78 * read(16, 0),
    0.45 * read(17, 0),
    0.20 * read(18, 0)
  );
  terrain = clamp(terrain, 0, 0.35);
  var terrainLift = clamp((terrain - 0.025) * 2.8, 0, 0.9);

  var hz = clamp(freq + speedGain * (targetSpeed - vx), 0.65, 3.3);
  var omega = 2 * PI * hz;

  if (!mem || typeof mem !== "object") mem = {};
  var phase;

  if (!mem._raceV1 ||
      typeof mem._phase !== "number" || !isFinite(mem._phase) ||
      typeof mem._lastT !== "number" || !isFinite(mem._lastT) ||
      t < mem._lastT - 0.001) {
    phase = phase0;
    mem._raceV1 = 1;
    mem._phase = phase;
    mem._lastT = t;
    mem._footA = footA ? 1 : 0;
    mem._footB = footB ? 1 : 0;
  } else {
    var dt = t - mem._lastT;
    if (!(dt > 0) || dt > 0.1 || !isFinite(dt)) dt = 1 / 60;
    phase = mem._phase + omega * dt;

    var correction = 0;
    var count = 0;
    if (footA && !mem._footA) {
      var ea = wrap(PI / 2 - phase);
      if (Math.abs(ea) < 1.4) {
        correction += ea;
        count++;
      }
    }
    if (footB && !mem._footB) {
      var eb = wrap(-PI / 2 - phase);
      if (Math.abs(eb) < 1.4) {
        correction += eb;
        count++;
      }
    }
    if (count > 0) phase += syncGain * correction / count;

    mem._phase = phase;
    mem._lastT = t;
    mem._footA = footA ? 1 : 0;
    mem._footB = footB ? 1 : 0;
  }

  var predictedLean = clamp(torsoAngle + balanceSpin * torsoSpin, -1.2, 1.2);
  var balance = -balanceGain * predictedLean;
  var heightError = clamp(desiredHeight - height, -0.35, 0.35);

  function legTargets(phi, foot) {
    var c = Math.cos(phi + kneePhase);
    var swing = Math.max(0, c);
    var swingControl = swing;
    var stance = Math.max(0, -c);
    if (foot) {
      swingControl *= 0.20;
      stance = 1;
    }

    var hip = hipBias +
      hipAmp * (Math.sin(phi) + hipShape * Math.sin(3 * phi)) +
      balance +
      0.65 * terrain * swing;

    var knee = kneeBase -
      kneeFlex * swingControl -
      terrainLift * swing;

    knee += heightGain * heightError * stance;

    hip = clamp(hip, -0.88, 1.18);
    knee = clamp(knee, -1.65, -0.055);
    return [hip, knee];
  }

  var a = legTargets(phase, footA);
  var b = legTargets(phase + PI, footB);

  var hipA = read(5, 0);
  var hipASpeed = read(6, 0);
  var kneeA = read(7, -0.12);
  var kneeASpeed = read(8, 0);
  var hipB = read(10, 0);
  var hipBSpeed = read(11, 0);
  var kneeB = read(12, -0.12);
  var kneeBSpeed = read(13, 0);

  return [
    clamp(hipKp * (a[0] - hipA) - hipKd * hipASpeed, -1, 1),
    clamp(kneeKp * (a[1] - kneeA) - kneeKd * kneeASpeed, -1, 1),
    clamp(hipKp * (b[0] - hipB) - hipKd * hipBSpeed, -1, 1),
    clamp(kneeKp * (b[1] - kneeB) - kneeKd * kneeBSpeed, -1, 1)
  ];
}

function learn(lab) {
  var lo = [
    0.9, -Math.PI, -0.4, 0.15, -0.25, -0.30, 0.15, -0.8,
    -1.5, -0.5, 0.12, 0.015, 0.12, 0.015, 0.9, 0,
    0, -0.25, 0.5
  ];
  var hi = [
    2.7, Math.PI, 0.4, 0.95, 0.25, -0.055, 1.3, 0.8,
    1.5, 0.5, 1.0, 0.18, 1.0, 0.18, 1.28, 1.5,
    0.4, 0.25, 3.5
  ];
  var defaults = [
    1.75, 0, 0.03, 0.58, 0, -0.12, 0.78, 0,
    0.75, 0.15, 0.50, 0.075, 0.45, 0.075, 1.07, 0.75,
    0.10, 0.05, 2.0
  ];
  var n = lo.length;

  function clamp(x, a, b) {
    return x < a ? a : (x > b ? b : x);
  }

  function reflect(x) {
    for (var k = 0; k < 6 && (x < -1 || x > 1); k++) {
      if (x > 1) x = 2 - x;
      else x = -2 - x;
    }
    return clamp(x, -1, 1);
  }

  function encode(j, value) {
    return reflect(2 * (value - lo[j]) / (hi[j] - lo[j]) - 1);
  }

  function gaussian() {
    var u = Math.max(Math.random(), 1e-12);
    var v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  var defaultZ = new Array(n);
  for (var j = 0; j < n; j++) defaultZ[j] = encode(j, defaults[j]);

  var budget = 1000;
  try {
    if (lab && typeof lab.trialsLeft === "function") {
      var available = lab.trialsLeft();
      if (typeof available === "number" && isFinite(available)) {
        budget = Math.min(1000, Math.max(0, Math.floor(available)));
      }
    }
  } catch (e) {}

  var bestZ = defaultZ.slice();
  var bestScore = -1e100;
  var evaluations = 0;

  function evaluate(z) {
    var result;
    try {
      result = lab.trial(z.slice());
    } catch (e) {
      evaluations++;
      return -1e6;
    }
    evaluations++;

    if (!result || result.outcome === "invalid" || result.outcome === "error") {
      return -1e6;
    }

    var distance = result.distance;
    if (typeof distance !== "number" || !isFinite(distance)) return -1e6;

    var time = result.time;
    if (typeof time !== "number" || !isFinite(time)) {
      time = result.outcome === "finished" ? 10 : 0;
    }
    if (result.outcome === "finished" && time <= 0) time = 10;
    time = clamp(time, 0, 10);

    var survival = time / 10;
    var score = distance * (0.4 + 0.6 * survival) +
      6 * survival +
      (result.outcome === "finished" ? 2 : 0);

    if (score > bestScore) {
      bestScore = score;
      bestZ = z.slice();
    }
    return score;
  }

  if (budget <= 0) return bestZ;

  var popSize = Math.min(40, budget);
  var population = new Array(popSize);
  var fitness = new Array(popSize);

  for (var i = 0; i < popSize; i++) {
    var z;

    if (i === 0) {
      z = defaultZ.slice();
    } else if (i === 1) {
      z = defaultZ.slice();
      z[8] = encode(8, -0.70);
    } else if (i === 2) {
      z = defaultZ.slice();
      z[0] = encode(0, 1.35);
      z[3] = encode(3, 0.70);
      z[6] = encode(6, 0.90);
    } else if (i === 3) {
      z = defaultZ.slice();
      z[0] = encode(0, 2.25);
      z[1] = encode(1, 1.0);
      z[3] = encode(3, 0.70);
    } else if (i === 4) {
      z = defaultZ.slice();
      z[10] = encode(10, 0.30);
      z[12] = encode(12, 0.30);
      z[6] = encode(6, 0.60);
    } else if (i === 5) {
      z = defaultZ.slice();
      z[1] = encode(1, -1.1);
      z[16] = encode(16, 0);
    } else if (i < Math.floor(popSize * 0.68)) {
      z = defaultZ.slice();
      for (j = 0; j < n; j++) {
        z[j] = reflect(z[j] + 0.22 * gaussian());
      }
    } else {
      z = new Array(n);
      for (j = 0; j < n; j++) z[j] = 2 * Math.random() - 1;
    }

    population[i] = z;
    fitness[i] = evaluate(z);
  }

  var generation = 0;
  while (evaluations < budget && popSize >= 4) {
    var snapshot = new Array(popSize);
    var oldFitness = fitness.slice();
    var bestIndex = 0;

    for (i = 0; i < popSize; i++) {
      snapshot[i] = population[i].slice();
      if (oldFitness[i] > oldFitness[bestIndex]) bestIndex = i;
    }

    var order = new Array(popSize);
    for (i = 0; i < popSize; i++) order[i] = i;
    for (i = popSize - 1; i > 0; i--) {
      var swap = Math.floor(Math.random() * (i + 1));
      var tmp = order[i];
      order[i] = order[swap];
      order[swap] = tmp;
    }

    var count = Math.min(popSize, budget - evaluations);
    var proposals = new Array(count);
    var proposalScores = new Array(count);

    for (var q = 0; q < count; q++) {
      var targetIndex = order[q];
      var target = snapshot[targetIndex];
      var useCurrentToBest = generation >= 4 && Math.random() < 0.70;
      var F = generation < 5
        ? 0.45 + 0.40 * Math.random()
        : 0.35 + 0.35 * Math.random();
      var mutant = new Array(n);

      if (useCurrentToBest) {
        var r1, r2;
        do { r1 = Math.floor(Math.random() * popSize); }
        while (r1 === targetIndex);
        do { r2 = Math.floor(Math.random() * popSize); }
        while (r2 === targetIndex || r2 === r1);

        for (j = 0; j < n; j++) {
          mutant[j] = target[j] +
            F * (bestZ[j] - target[j]) +
            F * (snapshot[r1][j] - snapshot[r2][j]);
        }
      } else {
        var a, b, c;
        do { a = Math.floor(Math.random() * popSize); }
        while (a === targetIndex);
        do { b = Math.floor(Math.random() * popSize); }
        while (b === targetIndex || b === a);
        do { c = Math.floor(Math.random() * popSize); }
        while (c === targetIndex || c === a || c === b);

        for (j = 0; j < n; j++) {
          mutant[j] = snapshot[a][j] +
            F * (snapshot[b][j] - snapshot[c][j]);
        }
      }

      var trialZ = new Array(n);
      var forced = Math.floor(Math.random() * n);
      var cr = generation < 5 ? 0.68 : 0.48;
      for (j = 0; j < n; j++) {
        trialZ[j] = (j === forced || Math.random() < cr)
          ? reflect(mutant[j])
          : target[j];
      }

      proposals[q] = [targetIndex, trialZ];
      proposalScores[q] = evaluate(trialZ);
    }

    for (q = 0; q < count; q++) {
      var index = proposals[q][0];
      if (proposalScores[q] > oldFitness[index]) {
        population[index] = proposals[q][1];
        fitness[index] = proposalScores[q];
      }
    }
    generation++;
  }

  return bestZ;
}

function policy(obs, params, mem) {
  var PI = Math.PI;
  var TAU = 2 * PI;

  function clamp(x, lo, hi) {
    return x < lo ? lo : (x > hi ? hi : x);
  }

  function read(i, fallback) {
    var x = obs && obs[i];
    return typeof x === "number" && isFinite(x) ? x : fallback;
  }

  function raw(i, fallback) {
    var z = fallback;
    if (params && typeof params.length === "number" &&
        i < params.length && typeof params[i] === "number" &&
        isFinite(params[i])) {
      z = params[i];
    }
    return clamp(z, -1, 1);
  }

  function par(i, lo, hi, fallback) {
    var z = raw(i, 2 * (fallback - lo) / (hi - lo) - 1);
    return lo + 0.5 * (z + 1) * (hi - lo);
  }

  function wrap(x) {
    x = (x + PI) % TAU;
    if (x < 0) x += TAU;
    return x - PI;
  }

  var freq = par(0, 0.8, 3.0, 1.8);
  var phase0 = par(1, -PI, PI, 0);
  var hipBias = par(2, -0.35, 0.35, 0);
  var hipAmp = par(3, 0.08, 1.0, 0.62);
  var hipShape = par(4, -0.30, 0.30, 0);
  var stanceFrac = par(5, 0.50, 0.74, 0.62);
  var hipDirection = raw(6, 1) >= 0 ? 1 : -1;
  var kneeBase = par(7, -0.30, -0.045, -0.12);
  var kneeFlex = par(8, 0.15, 1.35, 0.78);
  var leanTarget = par(9, -0.25, 0.12, -0.08);
  var balanceGain = par(10, -1.5, 1.5, 0.70);
  var balanceRate = par(11, -0.6, 0.6, 0.15);
  var swingBalance = par(12, 0, 0.8, 0.25);
  var hipKp = par(13, 0.12, 1.0, 0.55);
  var hipKd = par(14, 0.01, 0.22, 0.075);
  var kneeKp = par(15, 0.12, 1.0, 0.50);
  var kneeKd = par(16, 0.01, 0.22, 0.075);
  var desiredHeight = par(17, 0.98, 1.23, 1.08);
  var heightGain = par(18, 0, 1.5, 0.65);
  var syncGain = par(19, 0, 0.65, 0.16);
  var speedGain = par(20, -0.35, 0.35, 0.08);
  var targetSpeed = par(21, 0.4, 2.6, 1.3);
  var terrainGain = par(22, 0.4, 2.2, 1.25);

  var torsoAngle = read(0, 0);
  var torsoSpin = read(1, 0);
  var vx = read(2, 0);
  var height = read(4, 1.08);
  var footA = read(9, 0) > 0.5;
  var footB = read(14, 0) > 0.5;
  var t = read(19, 0);

  var ahead = Math.max(
    0,
    read(15, 0),
    0.78 * read(16, 0),
    0.50 * read(17, 0),
    0.28 * read(18, 0)
  );
  var terrain = clamp(ahead, 0, 0.35);

  var speedError = clamp(targetSpeed - vx, -2.5, 2.5);
  var hz = clamp(freq + speedGain * speedError, 0.65, 3.25);
  var omega = TAU * hz;
  var ampNow = hipAmp * clamp(1 + 0.14 * speedGain * speedError, 0.75, 1.25);

  if (!mem || typeof mem !== "object") mem = {};

  var phase;
  var fresh = mem._runnerV2 !== 1 ||
    typeof mem._phaseV2 !== "number" || !isFinite(mem._phaseV2) ||
    typeof mem._lastTV2 !== "number" || !isFinite(mem._lastTV2) ||
    t < mem._lastTV2 - 0.001;

  if (fresh) {
    phase = wrap(phase0);
  } else {
    var dt = t - mem._lastTV2;
    if (!(dt > 0) || dt > 0.1 || !isFinite(dt)) dt = 1 / 60;
    phase = wrap(mem._phaseV2 + omega * dt);

    var correction = 0;
    var count = 0;

    if (footA && !mem._footAV2) {
      var errA = wrap(-phase);
      if (Math.abs(errA) < 1.55) {
        correction += errA;
        count++;
      }
    }
    if (footB && !mem._footBV2) {
      var errB = wrap(PI - phase);
      if (Math.abs(errB) < 1.55) {
        correction += errB;
        count++;
      }
    }
    if (count > 0) phase = wrap(phase + syncGain * correction / count);
  }

  mem._runnerV2 = 1;
  mem._phaseV2 = phase;
  mem._lastTV2 = t;
  mem._footAV2 = footA ? 1 : 0;
  mem._footBV2 = footB ? 1 : 0;

  var tiltSeverity = clamp((Math.abs(torsoAngle) - 0.45) / 0.75, 0, 1);
  var balance = balanceGain *
    (leanTarget - torsoAngle - balanceRate * torsoSpin) *
    (1 + 0.35 * tiltSeverity);
  balance = clamp(balance, -0.95, 0.95);

  var heightError = clamp(desiredHeight - height, -0.35, 0.35);
  var stanceEnd = TAU * stanceFrac;

  function targets(phi, foot) {
    var p = phi % TAU;
    if (p < 0) p += TAU;

    var inStance = p < stanceEnd;
    var q;
    var h;
    var swing;

    if (inStance) {
      q = p / stanceEnd;
      h = Math.cos(PI * q) + hipShape * Math.sin(TAU * q);
      swing = 0;
    } else {
      q = (p - stanceEnd) / (TAU - stanceEnd);
      q = clamp(q, 0, 1);
      h = -Math.cos(PI * q) + hipShape * Math.sin(TAU * q);
      swing = Math.max(0, Math.sin(PI * q));
    }

    if (foot && !inStance) {
      h = -1;
      swing = 0;
    }

    var supportWeight = foot ? 1 : (inStance ? 0.78 : swingBalance);
    var heightWeight = foot ? 1 : (inStance ? 0.72 : 0.05);

    var hipTarget = hipBias +
      hipDirection * ampNow * h +
      0.45 * terrain * swing +
      balance * supportWeight;

    var kneeTarget = kneeBase -
      kneeFlex * swing -
      terrainGain * terrain * swing +
      heightGain * heightError * heightWeight;

    return [
      clamp(hipTarget, -0.87, 1.17),
      clamp(kneeTarget, -1.65, -0.055)
    ];
  }

  var a = targets(phase, footA);
  var b = targets(phase + PI, footB);

  var hipA = read(5, 0);
  var hipASpeed = read(6, 0);
  var kneeA = read(7, -0.12);
  var kneeASpeed = read(8, 0);
  var hipB = read(10, 0);
  var hipBSpeed = read(11, 0);
  var kneeB = read(12, -0.12);
  var kneeBSpeed = read(13, 0);

  return [
    clamp(hipKp * (a[0] - hipA) - hipKd * hipASpeed, -1, 1),
    clamp(kneeKp * (a[1] - kneeA) - kneeKd * kneeASpeed, -1, 1),
    clamp(hipKp * (b[0] - hipB) - hipKd * hipBSpeed, -1, 1),
    clamp(kneeKp * (b[1] - kneeB) - kneeKd * kneeBSpeed, -1, 1)
  ];
}

function learn(lab) {
  var PI = Math.PI;
  var lo = [
    0.8, -PI, -0.35, 0.08, -0.30, 0.50, -1,
    -0.30, 0.15, -0.25, -1.5, -0.6, 0,
    0.12, 0.01, 0.12, 0.01, 0.98, 0, 0,
    -0.35, 0.4, 0.4
  ];
  var hi = [
    3.0, PI, 0.35, 1.0, 0.30, 0.74, 1,
    -0.045, 1.35, 0.12, 1.5, 0.6, 0.8,
    1.0, 0.22, 1.0, 0.22, 1.23, 1.5, 0.65,
    0.35, 2.6, 2.2
  ];
  var defaults = [
    1.8, 0, 0, 0.62, 0, 0.62, 1,
    -0.12, 0.78, -0.08, 0.70, 0.15, 0.25,
    0.55, 0.075, 0.50, 0.075, 1.08, 0.65, 0.16,
    0.08, 1.3, 1.25
  ];
  var n = lo.length;

  function clamp(x, a, b) {
    return x < a ? a : (x > b ? b : x);
  }

  function reflect(x) {
    if (!isFinite(x)) return 0;
    for (var k = 0; k < 8 && (x < -1 || x > 1); k++) {
      if (x > 1) x = 2 - x;
      else x = -2 - x;
    }
    return clamp(x, -1, 1);
  }

  function encode(j, value) {
    if (j === 6) return value >= 0 ? 1 : -1;
    value = clamp(value, lo[j], hi[j]);
    return reflect(2 * (value - lo[j]) / (hi[j] - lo[j]) - 1);
  }

  function gaussian() {
    var u = Math.max(Math.random(), 1e-12);
    var v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * PI * v);
  }

  var defaultZ = new Array(n);
  for (var j = 0; j < n; j++) defaultZ[j] = encode(j, defaults[j]);

  var budget = 1000;
  try {
    if (lab && typeof lab.trialsLeft === "function") {
      var left = lab.trialsLeft();
      if (typeof left === "number" && isFinite(left)) {
        budget = Math.min(1000, Math.max(0, Math.floor(left)));
      }
    }
  } catch (e) {}

  if (!lab || typeof lab.trial !== "function" || budget <= 0) {
    return defaultZ;
  }

  var patches = [
    [],
    [[0, 1.30], [1, 0.40], [3, 0.72], [5, 0.66], [8, 0.90], [21, 1.0]],
    [[0, 2.15], [1, -0.40], [3, 0.76], [5, 0.60], [8, 0.95], [21, 1.7]],
    [[0, 2.65], [1, 0.60], [3, 0.82], [5, 0.56], [8, 1.05], [21, 2.0]],
    [[0, 1.55], [1, -1.0], [2, 0.04], [3, 0.85], [5, 0.68], [8, 0.72]],
    [[0, 1.8], [1, PI / 2], [3, 0.62], [5, 0.62]],
